import os, re, subprocess, sys
cmd=['cargo','test','-p','inir-mega','--manifest-path','native/Cargo.toml','pty_closed_slave_does_not_bypass_deadline_by_waiting_for_parent','--','--test-threads=1']
try:
    run=subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=110, check=False)
except subprocess.TimeoutExpired:
    print('PTY_EOF_DIAG=target_timeout')
    sys.exit(26)
combined=run.stdout+run.stderr
if len(combined)>65536:
    print('PTY_EOF_DIAG=output_cap')
    sys.exit(25)
if run.returncode==0:
    print('PTY_EOF_DIAG=target_pass')
    sys.exit(0)
src=open('native/inir-mega/src/pty.rs',encoding='utf-8').read().splitlines()
start=next((i for i,v in enumerate(src) if 'fn pty_closed_slave_does_not_bypass_deadline_by_waiting_for_parent' in v),None)
locs={int(n) for n in re.findall(rb'(?:src/pty\.rs|native/inir-mega/src/pty\.rs):(\d+):\d+',combined)}
if run.returncode==101 and start is not None:
    testlines=[(j+1,src[j]) for j in range(start,min(start+35,len(src)))]
    elapsed={n for n,s in testlines if 'assert!(started.elapsed()' in s}
    outcome={n for n,s in testlines if 'assert_eq!(result.unwrap().outcome' in s}
    if locs & elapsed:
        print('PTY_EOF_DIAG=elapsed_assertion')
        sys.exit(22)
    if locs & outcome:
        kind='unwrap_error' if b'called `Result::unwrap()` on an `Err` value' in combined else 'outcome_assertion'
        print('PTY_EOF_DIAG='+kind)
        sys.exit(21 if kind=='unwrap_error' else 23)
    if b'panicked at' in combined:
        print('PTY_EOF_DIAG=other_test_panic')
        sys.exit(24)
if b'could not compile' in combined:
    print('PTY_EOF_DIAG=compilation_failure')
    sys.exit(28)
print('PTY_EOF_DIAG=other_failure')
sys.exit(27)
